#!/usr/bin/env python3
"""Shared Drone Base Delivery Assignment solver."""

import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(SUB_DIR, "solution.csv")


def read_data():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)

    bases = {}
    base_order = []
    with open(os.path.join(DATA_DIR, "bases.csv")) as f:
        for row in csv.DictReader(f):
            b = row["base_id"]
            bases[b] = {
                "open_cost": float(row["open_cost"]),
                "sortie": int(row["daily_sortie_capacity"]),
                "battery_slots": int(row["battery_slots"]),
                "pilot_hours": float(row["pilot_shift_hours"]),
            }
            base_order.append(b)

    zones = {}
    zone_order = []
    with open(os.path.join(DATA_DIR, "demand_zones.csv")) as f:
        for row in csv.DictReader(f):
            z = row["zone_id"]
            zones[z] = {
                "packages": int(row["packages"]),
                "medical": int(row["medical_priority"]),
                "rate": float(row["minimum_service_rate"]),
            }
            zone_order.append(z)

    arcs = {}
    arc_list = []
    with open(os.path.join(DATA_DIR, "base_zone_arcs.csv")) as f:
        for row in csv.DictReader(f):
            z = row["zone_id"]
            b = row["base_id"]
            a = {
                "km": float(row["round_trip_km"]),
                "mins": float(row["flight_minutes"]),
                "payload": int(row["max_payload_packages"]),
                "cost": float(row["cost_per_package"]),
            }
            arcs[(b, z)] = a
            arc_list.append((b, z))

    return cfg, bases, base_order, zones, zone_order, arcs, arc_list


def solve():
    cfg, bases, base_order, zones, zone_order, arcs, arc_list = read_data()

    battery_cost = float(cfg.get("battery_lease_cost", 42.0))
    unserved_pen = float(cfg.get("unserved_penalty_per_package", 38.0))
    tol = float(cfg.get("feasibility_tolerance", 1e-05))

    time_limit = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env is not None:
        try:
            time_limit = min(time_limit, float(env))
        except ValueError:
            pass

    model = Model("drone_base_assignment")
    model.setParam("gaprel", 0.0005)
    model.setParam("limits/time", time_limit)

    # Variables
    y = {}
    for b in base_order:
        y[b] = model.addVar(name=f"y_{b}", vtype="B", lb=0, ub=1, obj=bases[b]["open_cost"])

    batt = {}
    for b in base_order:
        batt[b] = model.addVar(name=f"batt_{b}", vtype="I", lb=0, ub=bases[b]["battery_slots"], obj=battery_cost)

    x = {}
    for (b, z) in arc_list:
        x[(b, z)] = model.addVar(name=f"x_{b}_{z}", vtype="I", lb=0, ub=arcs[(b, z)]["payload"], obj=arcs[(b, z)]["cost"])

    u = {}
    for z in zone_order:
        u[z] = model.addVar(name=f"u_{z}", vtype="I", lb=0, ub=zones[z]["packages"], obj=unserved_pen)

    # Objective (explicit)
    obj_terms = []
    for b in base_order:
        obj_terms.append(bases[b]["open_cost"] * y[b])
    for b in base_order:
        obj_terms.append(battery_cost * batt[b])
    for (b, z) in arc_list:
        obj_terms.append(arcs[(b, z)]["cost"] * x[(b, z)])
    for z in zone_order:
        obj_terms.append(unserved_pen * u[z])
    model.setObjective(quicksum(obj_terms), sense="minimize")

    # Demand balance
    for z in zone_order:
        model.addCons(
            quicksum(x[(b, z)] for (b, zz) in arc_list if zz == z) + u[z] == zones[z]["packages"],
            name=f"bal_{z}",
        )

    # Service rate: unmet <= (1 - rate) * demand
    for z in zone_order:
        max_unmet = zones[z]["packages"] * (1.0 - zones[z]["rate"])
        model.addCons(u[z] <= max_unmet, name=f"svc_{z}")

    # Arc gating: x <= payload * y_b
    for (b, z) in arc_list:
        model.addCons(x[(b, z)] <= arcs[(b, z)]["payload"] * y[b], name=f"gate_{b}_{z}")

    # Base capacity constraints
    for b in base_order:
        bz_arcs = [(b, z) for (bb, z) in arc_list if bb == b]
        if not bz_arcs:
            continue
        # Sortie capacity
        model.addCons(
            quicksum(x[a] for a in bz_arcs) <= bases[b]["sortie"] * y[b],
            name=f"sortie_{b}",
        )
        # Pilot hours: flight_minutes * x <= 60 * hours * y
        model.addCons(
            quicksum(arcs[a]["mins"] * x[a] for a in bz_arcs) <= 60.0 * bases[b]["pilot_hours"] * y[b],
            name=f"pilot_{b}",
        )
        # Battery slots
        model.addCons(
            quicksum(x[a] for a in bz_arcs) <= batt[b],
            name=f"batt_{b}",
        )
        model.addCons(batt[b] <= bases[b]["battery_slots"] * y[b], name=f"battcap_{b}")

    # Solve
    status = "unknown"
    try:
        model.optimize()
        status = model.getStatus()
        print(f"SCIP Status: {status}")
        print(f"Solving Time: {model.getOrigTime():.2f}s")
        print(f"NSols: {model.getNSols()}")
    except Exception as e:
        print(f"Solver error: {e}")
        status = "error"

    # Extract solution
    open_bases = set()
    batt_vals = {}
    assign = {}
    unmet = {}

    if status in ("optimal", "bestsollimit", "gap", "timelimit") and model.getNSols() > 0:
        sol = model.getBestSol()
        for b in base_order:
            if model.getVal(y[b]) > 0.5:
                open_bases.add(b)
        for b in base_order:
            v = model.getVal(batt[b])
            batt_vals[b] = int(round(v))
        for (b, z) in arc_list:
            v = model.getVal(x[(b, z)])
            if v > 0.5:
                assign[(b, z)] = int(round(v))
        for z in zone_order:
            v = model.getVal(u[z])
            unmet[z] = int(round(v))
        print(f"Objective: {model.getObjVal():.4f}")
    else:
        # Fallback: heuristic — open all bases, assign each zone to cheapest arcs to meet service rate
        print("No MIP solution; using heuristic fallback.")
        open_bases = set(base_order)
        for b in base_order:
            batt_vals[b] = bases[b]["battery_slots"]

        # For each zone, pick cheapest arcs and assign to meet minimum service
        for z in zone_order:
            D = zones[z]["packages"]
            min_served = D - D * (1.0 - zones[z]["rate"])
            min_served = int(round(min_served))
            # Sort arcs for this zone by cost
            z_arcs = [(b, arcs[(b, z)]) for (b, zz) in arc_list if zz == z]
            z_arcs.sort(key=lambda t: t[1]["cost"])
            remaining = min_served
            for b, a in z_arcs:
                if remaining <= 0:
                    break
                take = min(a["payload"], remaining)
                if take > 0:
                    assign[(b, z)] = assign.get((b, z), 0) + take
                    remaining -= take
            # Unmet = D - served
            served = sum(v for (bb, zz), v in assign.items() if zz == z)
            unmet[z] = max(0, D - served)

    # Validation
    print("\n--- Validation ---")
    ok = True
    for z in zone_order:
        served = sum(v for (bb, zz), v in assign.items() if zz == z)
        bal = served + unmet.get(z, 0)
        D = zones[z]["packages"]
        if abs(bal - D) > tol:
            print(f"FAIL demand balance {z}: served={served} unmet={unmet.get(z,0)} total={bal} D={D}")
            ok = False
        max_unmet = D * (1.0 - zones[z]["rate"])
        if unmet.get(z, 0) > max_unmet + tol:
            print(f"FAIL service rate {z}: unmet={unmet.get(z,0)} max={max_unmet:.4f}")
            ok = False
    for (b, z), v in assign.items():
        if (b, z) not in arcs:
            print(f"FAIL arc not feasible: {b} -> {z}")
            ok = False
        if b not in open_bases:
            print(f"FAIL base not open: {b}")
            ok = False
        if v > arcs[(b, z)]["payload"]:
            print(f"FAIL payload exceeded: {b} -> {z} v={v} payload={arcs[(b,z)]['payload']}")
            ok = False
    print(f"Validation {'PASSED' if ok else 'FAILED'}")

    # Write solution
    os.makedirs(SUB_DIR, exist_ok=True)
    rows = []
    for b in base_order:
        if b in open_bases:
            rows.append(("open", b, "", 1))
    for b in base_order:
        v = batt_vals.get(b, 0)
        if v > 0 and b in open_bases:
            rows.append(("battery", b, "", v))
    for (b, z), v in sorted(assign.items()):
        if v > 0:
            rows.append(("assignment", b, z, v))
    for z in zone_order:
        v = unmet.get(z, 0)
        if v > 0:
            rows.append(("unmet", "", z, v))

    with open(SOLUTION_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type", "base_id", "zone_id", "value"])
        for r in rows:
            w.writerow(r)
    print(f"Wrote {SOLUTION_PATH} rows: {len(rows)}")


if __name__ == "__main__":
    solve()
